class A:
    def ping(self):
        print('A')

class B(A):
    def ping(self):
        super().ping()
        print('B')

b = B()
b.ping()

class Model:
    def __init__(self, table):
        self.table = table

class UserModel(Model):
    def __init__(self, table, db_url):
        super().__init__(table, db_url)
        self.db_url = db_url

u = UserModel('users', 'sqlite://')
